actions.script:
if (!ec.user.hasPermission('MONITOR_REPLAY')) { ec.web.sendJsonError(403, 'MONITOR_REPLAY permission is required') } else {
    const replay = ec.service.sync().name('org.moqui.monitor.MonitorServices.get#BrowserReplay').parameters({replayId}).call()
    if (ec.message.hasError()) { const errors = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonError(400, errors) }
    else ec.web.sendJsonResponse({events: replay.events || []})
}

replayAllowed = ec.user.hasPermission('MONITOR_REPLAY')
replayItems = []
if (replayAllowed) {
    const replay = ec.service.sync().name('org.moqui.monitor.MonitorServices.get#BrowserReplay').parameters({replayId}).call()
    const stamp = value => { const date = new Date(/^\d+$/.test(String(value)) ? Number(value) : value); return Number.isNaN(date.getTime()) ? String(value || '') : date.toISOString() }
    replayInfo = {userId: replay.userId, visitId: replay.visitId, url: replay.url, start: stamp(replay.start), end: stamp(replay.end), events: (replay.events || []).length}
    replayItems = [{time: replayInfo.start, title: replayInfo.url || '', text: ec.l10n.localize('{0} events; user {1}, visit {2}').replace('{0}', replayInfo.events).replace('{1}', replay.userId || '').replace('{2}', replay.visitId || ''), kind: 'info'}]
        .concat((replay.traceIds || []).map(traceId => ({time: '', title: 'Trace ' + traceId, text: '', kind: 'info', url: '/apps/monitor/TraceDetail?traceId=' + traceId})))
        .concat([{time: replayInfo.end, title: ec.l10n.localize('End'), text: ec.l10n.localize('Playback needs the web client.'), kind: 'info'}])
    traceLinks = (replay.traceIds || []).map(traceId => ({traceId}))
}
